pub fn next_delay(attempt: u32, config: &RetryConfig) -> u64 {
    // `attempt` is 1-based: the first retry must yield exactly
    // `base_delay_ms`, so doubling starts at attempt 2.
    let shift = attempt.saturating_sub(1);
    // Guard the shift: overflowing u64 truncates set bits (wrapping toward
    // zero) instead of saturating at the cap.
    let raw = if shift < 64 && config.base_delay_ms <= (u64::MAX >> shift) {
        config.base_delay_ms << shift
    } else {
        u64::MAX
    };
    raw.min(config.max_delay_ms)
}

